<?php require_once __DIR__.'/../includes/header.php';checkAuth(['admin']);$db=getDBConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['crear_categoria'])){$s=$db->prepare('INSERT OR IGNORE INTO categorias(nombre,orden) VALUES(?,?)');$s->execute([trim($_POST['categoria']),999]);$msg='Categoría guardada.';}elseif(isset($_POST['guardar_plato'])){$foto=null;if(!empty($_FILES['foto']['name']))$foto=uploadAndResizeImage($_FILES['foto'],'assets/uploads/dishes','dish_'.time().'_'.random_int(10,99),500);$s=$db->prepare('INSERT INTO platos(categoria_id,nombre,descripcion,ingredientes,guarniciones,precio_cup,foto_path,updated_at) VALUES(?,?,?,?,?,?,?,?)');$s->execute([(int)$_POST['categoria_id'],trim($_POST['nombre']),trim($_POST['descripcion']),trim($_POST['ingredientes']),trim($_POST['guarniciones']),(float)$_POST['precio_cup'],$foto,now()]);$msg='Producto añadido al menú.';}elseif(isset($_POST['toggle'])){$s=$db->prepare('UPDATE platos SET activo=1-activo,updated_at=? WHERE id=?');$s->execute([now(),(int)$_POST['id']]);$msg='Estado del producto actualizado.';}}$cats=$db->query('SELECT * FROM categorias WHERE activa=1 ORDER BY orden,nombre')->fetchAll();$rows=$db->query('SELECT p.*,c.nombre categoria FROM platos p JOIN categorias c ON c.id=p.categoria_id ORDER BY c.orden,c.nombre,p.nombre')->fetchAll();?><div class="grid grid-2"><div class="card"><h1>Nuevo producto</h1><p class="muted">El precio maestro se guarda en CUP; las demás monedas se calculan según la tasa configurada.</p><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="guardar_plato" value="1"><div><label>Nombre</label><input name="nombre" required></div><div><label>Categoría</label><select name="categoria_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['nombre'])?></option><?php endforeach;?></select></div><div><label>Precio base (CUP)</label><input type="number" step="0.01" min="0" name="precio_cup" required></div><div><label>Foto · 500×500</label><input type="file" name="foto" accept="image/*"></div><div class="full"><label>Descripción</label><textarea name="descripcion"></textarea></div><div class="full"><label>Ingredientes</label><textarea name="ingredientes"></textarea></div><div class="full"><label>Guarniciones</label><input name="guarniciones" placeholder="Opcional"></div><div class="full"><button class="btn gold">Publicar en el menú</button></div></form></div><div class="card"><h2>Categorías</h2><form method="post" class="actions"><input type="hidden" name="crear_categoria" value="1"><input name="categoria" placeholder="Nueva categoría" required><button class="btn olive">Añadir</button></form><p class="muted">Incluye categorías habituales de restaurante: entrantes, sopas, ensaladas, fuertes, casa, guarniciones, postres, bebidas, cócteles, vinos, cervezas, cafetería, desayunos y menú infantil.</p></div></div><div class="card"><h2>Menú maestro</h2><div class="table-wrap"><table><tr><th>Foto</th><th>Producto</th><th>Categoría</th><th>Precio CUP</th><th>Descripción</th><th>Estado</th></tr><?php foreach($rows as $p):?><tr><td><?php if($p['foto_path']):?><img class="thumb" src="<?=publicAsset($p['foto_path'])?>"><?php endif;?></td><td><b><?=h($p['nombre'])?></b><br><span class="muted"><?=h($p['ingredientes'])?></span></td><td><?=h($p['categoria'])?></td><td class="gold"><b><?=money((float)$p['precio_cup'])?></b></td><td><?=h($p['descripcion'])?><br><?= $p['guarniciones']?'<span class="muted">Guarnición: '.h($p['guarniciones']).'</span>':''?></td><td><form method="post"><input type="hidden" name="toggle" value="1"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn <?= $p['activo']?'olive':'danger'?>"><?=$p['activo']?'Activo':'Oculto'?></button></form></td></tr><?php endforeach;?></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
